import { Command } from 'commander';
import ora from 'ora';
import { git } from '../utils/git.js';

export function registerClean(program: Command) {
  program
    .command('clean')
    .description('Remove merged or stale branches')
    .option('-p, --prune-remote', 'Prune remote tracking branches')
    .action(async opts => {
      const spinner = ora('Cleaning branches...').start();
      const gitClient = git();
      const current = (await gitClient.status()).current;
      const merged = (await gitClient.branch(['--merged'])).all.filter(b => b !== current && b !== 'main' && b !== 'master');
      for (const branch of merged) {
        await gitClient.deleteLocalBranch(branch, true);
      }
      if (opts.pruneRemote) {
        await gitClient.raw(['remote', 'prune', 'origin']);
      }
      spinner.succeed(`Removed ${merged.length} merged branches.`);
    });
}
